insert into bd_days (slug, name, blurb, author_name, btown_pick, wants, mobility, budget, season, stops)
values
  ('parents-are-visiting', 'The Parents Are Visiting', 'Slow pace, good views, and nobody walks more than ten minutes.', 'Btown Brief', true, '{"outdoors","indoors","sit_down_dinner","quiet"}', 'low', 'mid', '{"Year-Round"}', '[{"ref":"rest:deep-city","min":660,"note":"Sit-down breakfast a block off the water."},{"ref":"thing:waterfront-park","min":720,"note":"Benches the whole way and the lake in front of you."},{"ref":"thing:echo-leahy-center","min":810,"note":"Indoors if it turns, and you can sit down in there."},{"ref":"rest:hen-of-the-wood","min":1080,"note":"Book it a week out. Opens at four on Saturdays."}]'::jsonb),
  ('broke-but-its-august', 'Broke But It''s August', 'Free the whole way through, except for one creemee at the end.', 'Btown Brief', true, '{"outdoors","free","cheap","water"}', 'normal', 'low', '{"Summer"}', '[{"ref":"thing:waterfront-park","min":660,"note":"Start here before the lot fills."},{"ref":"thing:burlington-greenway","min":810,"note":"North along the water as far as your legs want."},{"ref":"thing:texaco-beach","min":930,"note":"Everybody''s dog is here."},{"ref":"thing:battery-park","min":1110,"note":"Stay for the sunset. It''s the whole point."},{"ref":"rest:burlington-bay-creemee","min":1170,"note":"The one thing you pay for all day."}]'::jsonb),
  ('rainy-sunday-no-car', 'Rainy Sunday, No Car', 'Eight blocks, all of it indoors, and none of it a mall.', 'Btown Brief', true, '{"indoors","walkable","culture","cheap"}', 'normal', 'low', '{"Year-Round"}', '[{"ref":"rest:skinny-pancake","min":660,"note":"Start warm and dry."},{"ref":"thing:bca-center","min":780,"note":"Free, and small enough to do properly."},{"ref":"thing:burlington-records","min":900,"note":"An hour disappears in here."},{"ref":"thing:frog-hollow-gallery","min":990,"note":"Vermont makers, no pressure to buy."},{"ref":"thing:radio-bean","min":1110,"note":"Somebody is always playing something."}]'::jsonb),
  ('first-date-that-works', 'A First Date That Actually Works', 'Built for talking. Nothing here is so loud you have to lean in and shout.', 'Btown Brief', true, '{"quiet","drinks","sit_down_dinner","walkable"}', 'normal', 'mid', '{"Year-Round"}', '[{"ref":"thing:frog-hollow-gallery","min":1020,"note":"Something to talk about in the first ten minutes."},{"ref":"thing:foam-brewers","min":1080,"note":"One drink, outside if the patio''s open."},{"ref":"rest:pizzeria-verita","min":1170,"note":"Loud enough to be easy, quiet enough to hear."}]'::jsonb),
  ('new-in-town', 'New In Town', 'The day you give someone who just moved here and hasn''t found anything yet.', 'Btown Brief', true, '{"outdoors","walkable","culture","sit_down_dinner"}', 'normal', 'mid', '{"Year-Round"}', '[{"ref":"thing:burlington-farmers-market","min":630,"note":"This is where the town actually is on a Saturday."},{"ref":"thing:church-street-marketplace","min":750,"note":"Walk the whole block once, top to bottom."},{"ref":"thing:waterfront-park","min":870,"note":"Now you understand why people stay."},{"ref":"thing:foam-brewers","min":990,"note":"Sit outside and eavesdrop."},{"ref":"rest:american-flatbread","min":1110,"note":"The room everyone ends up in eventually."}]'::jsonb),
  ('four-hours-before-a-flight', 'Four Hours Before A Flight', 'Tight, walkable, and it ends fifteen minutes from the airport road.', 'Btown Brief', true, '{"walkable","indoors","cheap"}', 'normal', 'low', '{"Year-Round"}', '[{"ref":"thing:church-street-marketplace","min":660,"note":"One pass, no dawdling."},{"ref":"thing:outdoor-gear-exchange","min":750,"note":"The only souvenir worth carrying home."},{"ref":"rest:sherpa-kitchen","min":810,"note":"Fast, good, and open at lunch."}]'::jsonb),
  ('south-end-saturday', 'South End Saturday', 'Art in old factory buildings, then the breweries that moved in next door.', 'Btown Brief', true, '{"culture","drinks","walkable"}', 'normal', 'mid', '{"Year-Round"}', '[{"ref":"thing:south-end-arts-district","min":720,"note":"Start at the top of Pine and work down."},{"ref":"thing:pine-street-shops","min":840,"note":"Half of these didn''t exist five years ago."},{"ref":"thing:zero-gravity-brewery","min":960,"note":"Sit at the bar, not a table."},{"ref":"rest:la-reprise","min":1080,"note":"Four minutes from the brewery and open late."}]'::jsonb),
  ('with-kids-under-ten', 'With Kids, Under Ten', 'Somewhere to run, somewhere to hide from the weather, and food before the meltdown.', 'Btown Brief', true, '{"kids","outdoors","indoors","cheap"}', 'normal', 'low', '{"Year-Round"}', '[{"ref":"thing:waterfront-park","min":600,"note":"Burn the first two hours here."},{"ref":"thing:echo-leahy-center","min":720,"note":"The indoor half of the day, whatever the sky says."},{"ref":"rest:skinny-pancake","min":840,"note":"Crepes, and nobody minds the noise."}]'::jsonb),
  ('a-weird-burlington-day', 'A Weird Burlington Day', 'For when you''ve lived here six years and keep doing the same three things. You''ll want a car.', 'Btown Brief', true, '{"culture","walkable","cheap"}', 'normal', 'low', '{"Year-Round"}', '[{"ref":"thing:ethan-allen-homestead","min":660,"note":"Nobody who lives here has been. Go anyway."},{"ref":"thing:autumn-records","min":840,"note":"Winooski, ten minutes, worth the bridge."},{"ref":"thing:barge-canal-market","min":960,"note":"Furniture you don''t need and will think about all week."},{"ref":"thing:vermont-comedy-club","min":1140,"note":"Cheap seats, and the late show is the better one."}]'::jsonb),
  ('cheap-date-night', 'Cheap Date Night', 'Under forty dollars for two, and it doesn''t feel like it.', 'Btown Brief', true, '{"cheap","quiet","drinks","walkable"}', 'normal', 'low', '{"Year-Round"}', '[{"ref":"thing:battery-park","min":1110,"note":"Sunset first. It''s free and it does the work."},{"ref":"rest:sherpa-kitchen","min":1170,"note":"Momos, and the bill won''t frighten anybody."},{"ref":"thing:radio-bean","min":1260,"note":"Whatever''s on is on. That''s the deal."}]'::jsonb)
